using Keynote.Input;
using Keynote.Core;
using Keynote.Playback;
namespace Keynote.Tests;
public class HotkeyIntegrationTests {
 [Fact] public void ShortcutAcknowledgesItsOwnPhysicalInputPauseBeforeResuming() { bool pending=true; int resumes=0; var control=new PlaybackHotkeyController(()=>PlaybackState.Paused,()=>true,()=>{},()=>{},()=>resumes++,()=>Task.CompletedTask,()=> { var result=pending; pending=false; return result; }); control.Toggle(); Assert.Equal(0,resumes); control.Toggle(); Assert.Equal(1,resumes); }
 sealed class FakePlatform : IHotkeyPlatform {
  public Dictionary<int,Hotkey> Registrations=new(); public HashSet<Hotkey> Conflicts=new(); public bool Register(int id,Hotkey key) { if(Conflicts.Contains(key)||Registrations.ContainsValue(key)||Registrations.ContainsKey(id))return false; Registrations[id]=key; return true; } public bool Unregister(int id)=>Registrations.Remove(id);
 }
 static readonly Hotkey Toggle=new(HotkeyModifiers.Control|HotkeyModifiers.Alt,0x77), Stop=new(HotkeyModifiers.Control|HotkeyModifiers.Alt,0x78);
 [Fact] public void RegistersDispatchesAndUnregistersBoth() { var platform=new FakePlatform(); var service=new GlobalHotkeyService(platform); var calls=new List<HotkeyCommand>(); service.Triggered+=calls.Add; Assert.True(service.Register(Toggle,Stop,out _)); service.Dispatch(1);service.Dispatch(2);service.Dispatch(99);Assert.Equal(new[]{HotkeyCommand.TogglePlayback,HotkeyCommand.EmergencyStop},calls);service.Dispose();Assert.Empty(platform.Registrations);service.Dispatch(1);Assert.Equal(2,calls.Count); }
 [Fact] public void ConflictRestoresPreviousPairAndReportsFailure() { var platform=new FakePlatform(); using var service=new GlobalHotkeyService(platform); Assert.True(service.Register(Toggle,Stop,out _)); var other=new Hotkey(HotkeyModifiers.Control,0x70); platform.Conflicts.Add(other); Assert.False(service.Register(other,Stop,out var error)); Assert.Contains("failed",error,StringComparison.OrdinalIgnoreCase); Assert.Equal(Toggle,platform.Registrations[1]);Assert.Equal(Stop,platform.Registrations[2]); }
 [Fact] public void SecondRegistrationConflictRollsBackFirst() { var platform=new FakePlatform(); using var service=new GlobalHotkeyService(platform); platform.Conflicts.Add(Stop); Assert.False(service.Register(Toggle,Stop,out _)); Assert.Empty(platform.Registrations); }
 [Fact] public void RejectsDuplicateOrInvalidShortcutsWithoutDisturbingCurrentPair() { var platform=new FakePlatform(); using var service=new GlobalHotkeyService(platform); Assert.True(service.Register(Toggle,Stop,out _)); Assert.False(service.Register(Toggle,Toggle,out _)); Assert.False(service.Register(new(0,0x77),Stop,out _)); Assert.Equal(2,platform.Registrations.Count); }
 [Fact] public void NewlyReadySongCanStartAfterPreviousFault() { var state=PlaybackState.Faulted; var starts=0; var control=new PlaybackHotkeyController(()=>state,()=>true,()=>starts++,()=>{},()=>{},()=>Task.CompletedTask); control.Toggle(); Assert.Equal(0,starts); control.SetReady(true); control.Toggle(); Assert.Equal(1,starts); }
 [Fact] public async Task DispatchControlsPlaybackOnlyWhenAllowedWithoutWindowActivation() { var platform=new FakePlatform(); using var service=new GlobalHotkeyService(platform); var state=PlaybackState.Stopped; bool foreground=false; int starts=0,pauses=0,resumes=0,stops=0; var control=new PlaybackHotkeyController(()=>state,()=>foreground,()=>{starts++;state=PlaybackState.Playing;},()=>{pauses++;state=PlaybackState.Paused;},()=>{resumes++;state=PlaybackState.Playing;},()=>{stops++;state=PlaybackState.Stopped;return Task.CompletedTask;}); control.SetReady(true); service.Triggered+=c=>{if(c==HotkeyCommand.TogglePlayback)control.Toggle(); else control.EmergencyStop().GetAwaiter().GetResult();}; Assert.True(service.Register(Toggle,Stop,out _)); service.Dispatch(1); Assert.Equal(0,starts); foreground=true;service.Dispatch(1);Assert.Equal(1,starts);service.Dispatch(1);Assert.Equal(1,pauses);foreground=false;service.Dispatch(1);Assert.Equal(0,resumes);foreground=true;service.Dispatch(1);Assert.Equal(1,resumes);service.Dispatch(2);Assert.Equal(1,stops);service.Dispatch(1);Assert.Equal(1,starts);await Task.CompletedTask; }
}
